// Scheduled source-backed reports. Server snapshots are generated by Supabase cron.
import {getClient} from './backend.js';
const el=(tag,text='',cls='')=>{const n=document.createElement(tag);n.textContent=text;if(cls)n.className=cls;return n;};
let box=null,db=null,user=null;
const note=t=>{const n=box?.querySelector('[data-report-status]');if(n)n.textContent=t;};
async function session(){
 db=await getClient();const {data,error}=await db.auth.getUser();user=error?null:data?.user;
 if(!user){note('請先登入，才能儲存報表排程並讀取自己的報表。');return false;}
 return true;
}
const kinds={daily_cases:'標案清單',monthly_market:'市場採購分析',my_pipeline:'我的投標案件'};
const freqs={daily:'每日（前一天）',weekly:'每週（前七天）',monthly:'每月（前一個月）'};
function downloadReport(job){
 const payload=job.result_data||{},rows=Array.isArray(payload.rows)?payload.rows:[],
 columns=Array.isArray(payload.columns)?payload.columns:[];
 if(!columns.length){note('這份報表沒有完整的欄位資料，請重新產生。');return;}
 const escape=v=>{
  let s=v===null||v===undefined?'':String(v);
  if(/^[=+@\-\t\r]/.test(s))s="'"+s;
  return '"'+s.replace(/"/g,'""')+'"';
 };
 const lines=[columns,...rows.map(r=>columns.map(c=>r[c]))];
 const csv='\uFEFF'+lines.map(r=>r.map(escape).join(',')).join('\r\n');
 const file=new Blob([csv],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(file),a=document.createElement('a');
 a.href=url;a.download='標案報表_'+(job.report_type||'report')+'_'+String(job.created_at||'').slice(0,10)+'.csv';a.click();
 setTimeout(()=>URL.revokeObjectURL(url),1000);
 note('已匯出 '+rows.length+' 筆／組報表資料。數字只代表實際已入庫來源。');
}
async function reload(){
 if(!box||!(await session()))return;
 const [{data:schedules,error:a},{data:jobs,error:b}]=await Promise.all([
  db.from('ti_report_schedules').select('id,title,report_type,frequency,keyword,agency,enabled,last_report_on').eq('user_id',user.id).order('created_at',{ascending:false}).limit(80),
  db.from('ti_report_jobs').select('id,title,report_type,schedule_id,filters,created_at,finished_at,status,result_data,error_summary').eq('user_id',user.id).order('created_at',{ascending:false}).limit(50)
 ]);
 if(a||b){note('讀取報表失敗：'+(a||b).message);return;}
 const list=box.querySelector('[data-report-schedules]'),out=box.querySelector('[data-report-results]');
 list.replaceChildren();out.replaceChildren();
 if(!schedules?.length)list.append(el('p','尚未建立自動報表排程。','minor'));
 for(const sch of schedules||[]){
  const row=el('div','','ti-case-listrow'),left=el('div','','ti-report-item'),name=el('strong',sch.title||kinds[sch.report_type]);
  const lastSuccess=(jobs||[]).find(j=>(j.schedule_id===sch.id||j.filters?.schedule_id===sch.id)&&j.status==='completed');
  left.append(name,el('p',kinds[sch.report_type]+'｜'+freqs[sch.frequency]+(sch.keyword?'｜關鍵字：'+sch.keyword:'')+
   (sch.agency?'｜機關：'+sch.agency:'')+'｜最近完成：'+(lastSuccess?.finished_at?new Date(lastSuccess.finished_at).toLocaleString('zh-TW',{timeZone:'Asia/Taipei'}):(sch.last_report_on||'尚未')),'minor'));
  const generate=el('button','立即產生一次','ghost-btn');generate.type='button';
  generate.addEventListener('click',async()=>{
   if(!(await session()))return;
   generate.disabled=true;generate.textContent='產生中…';
   try{
    const {data,error}=await db.rpc('ti_generate_report_now',{p_schedule_id:sch.id});
    if(error)throw error;
    await reload();
    note('已立即產生報表，可在下方預覽與下載 CSV。');
   }catch(error){note('報表產生失敗：'+error.message);}
   finally{generate.disabled=false;generate.textContent='立即產生一次';}
  });
  const toggle=el('button',sch.enabled?'暫停':'啟用','ghost-btn');toggle.type='button';
  toggle.addEventListener('click',async()=>{
   toggle.disabled=true;const {error}=await db.from('ti_report_schedules').update({enabled:!sch.enabled}).eq('user_id',user.id).eq('id',sch.id);
   if(error)note('變更排程失敗：'+error.message);await reload();
  });
  const remove=el('button','刪除排程','ghost-btn');remove.type='button';
  remove.addEventListener('click',async()=>{
   if(!window.confirm('確定刪除此報表排程？先前已產出的報表仍會保存。'))return;
   remove.disabled=true;const {error}=await db.from('ti_report_schedules').delete().eq('id',sch.id).eq('user_id',user.id);
   if(error)note('刪除失敗：'+error.message);await reload();
  });row.append(left,generate,toggle,remove);list.append(row);
 }
 if(!jobs?.length)out.append(el('p','排程會在符合日期的早上產生報表，完成後可以下載。','minor'));
 for(const job of jobs||[]){
  const row=el('div','','ti-case-listrow'),detail=el('div','','ti-report-item');
  const count=Array.isArray(job.result_data?.rows)?job.result_data.rows.length:0;
  detail.append(el('strong',job.title||kinds[job.report_type]),el('p',(job.created_at||'').slice(0,16).replace('T',' ')+'｜'+
    (job.status==='completed'?'已完成':'狀態：'+job.status)+'｜'+count+' 筆／組｜'+(job.error_summary||job.result_data?.description||''),'minor'));
  const button=el('button','下載 CSV','ghost-btn');button.type='button';button.disabled=job.status!=='completed';
  button.addEventListener('click',()=>downloadReport(job));
  const previewButton=el('button','預覽內容','ghost-btn');previewButton.type='button';previewButton.disabled=job.status!=='completed';
  const preview=el('div','','ti-report-preview');preview.hidden=true;
  previewButton.addEventListener('click',()=>{
   preview.hidden=!preview.hidden;previewButton.textContent=preview.hidden?'預覽內容':'收起預覽';
   if(preview.hidden||preview.childElementCount)return;
   const columns=Array.isArray(job.result_data?.columns)?job.result_data.columns:[],
    entries=Array.isArray(job.result_data?.rows)?job.result_data.rows:[],
    limited=columns.slice(0,7),table=document.createElement('table');
   const head=document.createElement('tr');
   for(const key of limited){const th=el('th',key);head.append(th);}
   table.append(head);
   for(const item of entries.slice(0,8)){
    const tr=document.createElement('tr');
    for(const key of limited)tr.append(el('td',String(item?.[key]??'尚無資料').slice(0,160)));
    table.append(tr);
   }
   preview.append(table,el('p','僅預覽前 '+Math.min(entries.length,8)+' 筆；匯出時保留這份報表全部 '+entries.length+' 筆／組。','minor'));
   if(!entries.length)preview.prepend(el('p','這個條件在目前入庫範圍內沒有資料。','notice'));
  });
  row.append(detail,previewButton,button);
  const wrap=el('div','','ti-report-result');wrap.append(row,preview);out.append(wrap);
 }
 note('已載入 '+(schedules?.length||0)+' 個排程與 '+(jobs?.length||0)+' 份報表。資料按實際已入庫案件生成。');
}
async function create(ev){
 ev.preventDefault();if(!(await session()))return;
 const form=box.querySelector('form'),button=form.querySelector('button[type="submit"]');
 const title=form.elements.namedItem('reportTitle').value.trim(),
 report_type=form.elements.namedItem('reportType').value,
 frequency=form.elements.namedItem('reportFrequency').value,
 keyword=form.elements.namedItem('reportKeyword').value.trim(),
 agency=form.elements.namedItem('reportAgency').value.trim();
 button.disabled=true;
 try{
  const {error}=await db.from('ti_report_schedules').insert({user_id:user.id,title:title||kinds[report_type],
   report_type,frequency,keyword:keyword.slice(0,100),agency:agency.slice(0,100)});
  if(error)throw error;form.reset();await reload();
 }catch(x){note('新增排程失敗：'+x.message)}finally{button.disabled=false;}
}
function init(){
 const section=document.getElementById('view-alerts');if(!section)return;
 box=el('section','','panel analysis-panel ti-report-module');
 const header=el('h2','自動標案與市場報表'),
 desc=el('p','排程由伺服器執行，不需要開著網頁。每天上午 08:20（台灣時間）檢查排程；週報每週一，月報每月 1 日。','minor');
 const form=document.createElement('form');form.className='ti-report-form';
 const title=document.createElement('input');title.name='reportTitle';title.maxLength=180;title.placeholder='報表名稱（選填）';
 const types=document.createElement('select');types.name='reportType';
 for(const [key,label] of Object.entries(kinds)){const o=el('option',label);o.value=key;types.append(o);}
 const frequency=document.createElement('select');frequency.name='reportFrequency';
 for(const [key,label] of Object.entries(freqs)){const o=el('option',label);o.value=key;frequency.append(o);}
 const keyword=document.createElement('input');keyword.name='reportKeyword';keyword.maxLength=100;keyword.placeholder='標案關鍵字（選填）';
 const agency=document.createElement('input');agency.name='reportAgency';agency.maxLength=100;agency.placeholder='機關名稱（選填）';
 const btn=el('button','建立報表排程','primary-btn');btn.type='submit';
 for(const [label,input] of [['名稱',title],['報表類型',types],['週期',frequency],['關鍵字',keyword],['指定機關',agency]]){
  const wrapper=el('label',label);wrapper.append(input);form.append(wrapper);
 }
 form.append(btn);
 const schedules=el('div','','ti-case-list'),outputs=el('div','','ti-case-list');
 schedules.dataset.reportSchedules='1';outputs.dataset.reportResults='1';
 const status=el('p','請先登入，再建立自動報表。','minor');status.dataset.reportStatus='1';
 box.append(header,desc,form,el('h3','我的排程'),schedules,el('h3','已產生的報表'),outputs,status);
 section.append(box);form.addEventListener('submit',e=>void create(e));
 document.addEventListener('ti:view-changed',event=>{if(event.detail?.view==='alerts')void reload();});
 getClient().then(c=>c.auth.onAuthStateChange(()=>{if(!section.hidden)void reload();})).catch(()=>{});
}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
